package com.zhucanle.opencodev2.ide

import com.zhucanle.opencodev2.ide.util.ServiceEndpoint
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Unit tests for [OpenCodeService.resolveConnectionAuth].
 *
 * opencode v2 runs a service-managed local background service whose password is generated by the
 * service itself. For local hosts the credentials must therefore always come from
 * [com.zhucanle.opencodev2.ide.util.OpenCodeServiceDiscovery] (the `service.json` endpoint), never from
 * the password typed into the connect dialog. The dialog password keeps its meaning for remote hosts.
 */
class OpenCodeServiceAuthTest {

    @Test
    fun localHostUsesDiscoveredPasswordInsteadOfDialogPassword() {
        val auth = OpenCodeService.resolveConnectionAuth(
            local = true,
            dialogPassword = "dialog-password",
            discover = { ServiceEndpoint("127.0.0.1", 49374, "discovered-password") }
        )

        assertEquals("opencode", auth.username)
        assertEquals("discovered-password", auth.password)
    }

    @Test
    fun localHostWithoutDiscoveryUsesNullPasswordAndNotTheDialogPassword() {
        val auth = OpenCodeService.resolveConnectionAuth(
            local = true,
            dialogPassword = "dialog-password",
            discover = { null }
        )

        assertEquals("opencode", auth.username)
        assertNull("A local endpoint must never fall back to the dialog password", auth.password)
    }

    @Test
    fun localHostAlwaysConsultsDiscovery() {
        var consulted = false
        OpenCodeService.resolveConnectionAuth(local = true, dialogPassword = "dialog-password") {
            consulted = true
            ServiceEndpoint("127.0.0.1", 49374, "discovered-password")
        }

        assertTrue("Local auth must be resolved through service discovery", consulted)
    }

    @Test
    fun remoteHostUsesDialogPasswordAndSkipsDiscovery() {
        var consulted = false
        val auth = OpenCodeService.resolveConnectionAuth(local = false, dialogPassword = "dialog-password") {
            consulted = true
            ServiceEndpoint("10.0.0.5", 49374, "discovered-password")
        }

        assertEquals("opencode", auth.username)
        assertEquals("dialog-password", auth.password)
        assertFalse("Remote auth must not touch the local service discovery", consulted)
    }
}
